//     values.combo3Img    = '/assets/US/group_507.webp'
//     values.combo6Img    = '/assets/US/group_520.webp'

//   } else 
  if (currency === 'CAD') {
    values.oldValue     = '$99'
    values.currentValue = '$85'
    values.threeBottles = '$59'
    values.sixBottles   = '$42'
    values.imagePath    = '/assets/nerve_ca1.webp'
    values.combo3Img    = '/assets/CA/nerve_3_CA.webp'
    values.combo6Img    = '/assets/CA/nerve_6_CA.webp'

  } else if (currency === 'GBP') {
    values.oldValue     = '£59'
    values.currentValue = '£49'
    values.threeBottles = '£35'
    values.sixBottles   = '£25'
    values.imagePath    = '/assets/nerve_uk1.webp'
    values.combo3Img    = '/assets/UK/nerve_3_UK.webp'
    values.combo6Img    = '/assets/UK/nerve_6_UK.webp'
  } else {
    // USD (default)
    values.oldValue     = '$69'
    values.currentValue = '$59'
    values.threeBottles = '$39'
    values.sixBottles   = '$29'
    values.imagePath    = '/assets/nerve_us1.webp'
    values.combo3Img    = '/assets/US/nerve_3_us.webp'
    values.combo6Img    = '/assets/US/nerve_6_us.webp'
  }
})

